vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string t;
    cin >> t;
    string p;
    cin >> p;
    long long q;
    cin >> q;
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    int n = (int)t.size(), m = (int)p.size();
    string c = p + "#" + t;
    vector<int> pi = prefixFunction(c);
    vector<long long> pref(n + 2, 0);
    for (int i = m + 1; i < (int)c.size(); i++) if (pi[i] == m) pref[i - 2 * m + 1]++;
    for (int i = 1; i < n + 2; i++) pref[i] += pref[i - 1];
    string out;
    for (long long k = 0; k < q; k++) {
        long long l = qs[k][0], rr = qs[k][1];
        long long ans = (rr - l + 1 < m) ? 0 : pref[rr - m + 1] - pref[l - 1];
        if (k) out += " ";
