import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] prefixFunction(String s) {
        int n = s.length();
        int[] pi = new int[n];
        for (int i = 1; i < n; i++) {
            int k = pi[i - 1];
            while (k > 0 && s.charAt(i) != s.charAt(k)) k = pi[k - 1];
            if (s.charAt(i) == s.charAt(k)) k++;
            pi[i] = k;
        }
        return pi;
    }

    public static void main(String[] args) throws IOException {
        String t = next();
        String p = next();
        long q = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int n = t.length(), m = p.length();
        String c = p + "#" + t;
        int[] pi = prefixFunction(c);
        long[] pref = new long[n + 2];
        for (int i = m + 1; i < c.length(); i++) if (pi[i] == m) pref[i - 2 * m + 1]++;
        for (int i = 1; i < n + 2; i++) pref[i] += pref[i - 1];
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            int l = (int) qs[k][0], rr = (int) qs[k][1];
            long ans = (rr - l + 1 < m) ? 0 : pref[rr - m + 1] - pref[l - 1];
            if (k > 0) out.append(" ");
            out.append(ans);
        }
        System.out.println(out);
    }
}
